// =====================================================
// FAST 1-BIT BITMAP DRAWER WITH HARDWARE SPAN ACCELERATION
// =====================================================
inline void drawBitmap1BitFast(int x, int y, const uint8_t *bitmap, int w, int h, uint16_t color)
{
  if (!bitmap || w <= 0 || h <= 0) return;
  int byteWidth = (w + 7) / 8;
  for (int j = 0; j < h; j++)
  {
    int start_x = -1;
    int len = 0;
    for (int i = 0; i < w; i++)
    {
      uint8_t b = pgm_read_byte(&bitmap[j * byteWidth + (i / 8)]);
      if (b & (0x80 >> (i % 8)))
      {
        if (start_x < 0) { start_x = i; len = 1; }
        else { len++; }
      }
      else
      {
        if (start_x >= 0)
        {
          tft.drawFastHLine(x + start_x, y + j, len, color);
          start_x = -1;
          len = 0;
        }
      }
    }
    if (start_x >= 0)
    {
      tft.drawFastHLine(x + start_x, y + j, len, color);
    }
  }
}

// =====================================================
// FAST HEX-STRING 1-BIT BITMAP DRAWER (FOR DYNAMIC TEXT FROM PC)
// =====================================================
inline void drawHexBitmap1Bit(int x, int y, const char *hex_str, int w, int h, uint16_t color)
{
  if (!hex_str || hex_str[0] == '\0' || w <= 0 || h <= 0) return;
  int byteWidth = (w + 7) / 8;
  int hex_len = strlen(hex_str);

  for (int j = 0; j < h; j++)
  {
    int start_x = -1;
    int len = 0;
    for (int i = 0; i < w; i++)
    {
      int byte_idx = j * byteWidth + (i / 8);
      int hex_pos = byte_idx * 2;
      if (hex_pos + 1 >= hex_len) break;

      char h1 = hex_str[hex_pos];
      char h2 = hex_str[hex_pos + 1];
      uint8_t v1 = (h1 >= 'a') ? (h1 - 'a' + 10) : ((h1 >= 'A') ? (h1 - 'A' + 10) : (h1 - '0'));
      uint8_t v2 = (h2 >= 'a') ? (h2 - 'a' + 10) : ((h2 >= 'A') ? (h2 - 'A' + 10) : (h2 - '0'));
      uint8_t b = (v1 << 4) | v2;

      if (b & (0x80 >> (i % 8)))
      {
        if (start_x < 0) { start_x = i; len = 1; }
        else { len++; }
      }
      else
      {
        if (start_x >= 0)
        {
          tft.drawFastHLine(x + start_x, y + j, len, color);
          start_x = -1;
          len = 0;
        }
      }
    }
    if (start_x >= 0)
    {
      tft.drawFastHLine(x + start_x, y + j, len, color);
    }
  }
}


// =====================================================
// FALLBACK DYNAMIC TEXT DRAWER
// =====================================================
inline void drawArabicDynamicText(const String &txt, int center_x, int top_y, uint16_t color)
{
  tft.setTextColor(color, TFT_BLACK);
  tft.setTextDatum(TC_DATUM);
  tft.drawString(txt, center_x, top_y);
}

